def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into individual letters
    letters = test.split()

    # Initialize an empty dictionary to store the frequency of each letter
    freq_dict = {}

    # Iterate over each letter in the list
    for letter in letters:
        # Increment the count of the letter in the dictionary
        if letter in freq_dict:
            freq_dict[letter] += 1
        else:
            freq_dict[letter] = 1

    # Find the maximum frequency among all letters
    max_freq = max(freq_dict.values(), default=0)

    # Create a new dictionary containing only the letters with the maximum frequency
    result = {letter: count for letter, count in freq_dict.items() if count == max_freq}

    return result

